'use client';

import * as React from 'react';
import { Accordion as AccordionPrimitive } from 'radix-ui';
import { ChevronDown } from '@/components/icons';
import { cn } from '@/lib/cn';

function Accordion({ className, ...props }: React.ComponentProps<typeof AccordionPrimitive.Root>) {
  return <AccordionPrimitive.Root className={cn('flex w-full flex-col', className)} {...props} />;
}

function AccordionItem({ className, ...props }: React.ComponentProps<typeof AccordionPrimitive.Item>) {
  return (
    /* design-check-exempt: Accordion Item is a structural container; its nested Trigger owns interaction. */
    <AccordionPrimitive.Item
      className={cn('border-b border-[var(--color-border)] last:border-b-0', className)}
      {...props}
    />
  );
}

function AccordionTrigger({ className, children, ...props }: React.ComponentProps<typeof AccordionPrimitive.Trigger>) {
  return (
    <AccordionPrimitive.Header className="flex">
      <AccordionPrimitive.Trigger
        className={cn(
          'group flex min-h-[var(--touch-target-min)] flex-1 cursor-pointer items-center justify-between',
          'gap-[var(--space-3)] rounded-[var(--radius-sm)] px-[var(--space-2)] py-[var(--space-2)] text-left',
          'text-[length:var(--text-sm)] font-medium text-[var(--color-text-primary)]',
          'transition-colors duration-[var(--duration-fast)] ease-[var(--ease-out)]',
          'hover:bg-[var(--color-surface-hover)]',
          'active:bg-[var(--color-surface-active)]',
          'disabled:cursor-not-allowed disabled:opacity-50',
          className
        )}
        {...props}
      >
        {children}
        <ChevronDown
          size={16}
          aria-hidden="true"
          className="shrink-0 text-[var(--color-text-secondary)] transition-transform duration-[var(--duration-base)] ease-[var(--ease-out)] group-data-[state=open]:rotate-180"
        />
      </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
  );
}

function AccordionContent({ className, children, ...props }: React.ComponentProps<typeof AccordionPrimitive.Content>) {
  return (
    <AccordionPrimitive.Content
      className="overflow-hidden text-[length:var(--text-sm)] text-[var(--color-text-secondary)]"
      {...props}
    >
      <div className={cn('px-[var(--space-2)] pb-[var(--space-4)] pt-[var(--space-1)]', className)}>{children}</div>
    </AccordionPrimitive.Content>
  );
}

export { Accordion, AccordionContent, AccordionItem, AccordionTrigger };

'use client';

// Radix provides role=alertdialog, focus trapping, focus return, Escape, and
// outside-click protection. The AlertDialog export supports both the canonical
// composable root API and the original controlled convenience API.

import * as React from 'react';
import * as AlertDialogPrimitive from '@radix-ui/react-alert-dialog';
import { buttonVariants } from '@/components/ui/button';
import { cn } from '@/lib/cn';

export interface AlertDialogProps {
  open: boolean;
  title: string;
  description?: React.ReactNode;
  confirmLabel?: string;
  cancelLabel?: string;
  destructive?: boolean;
  confirmDisabled?: boolean;
  onConfirm: () => void;
  onCancel: () => void;
  className?: string;
}

type AlertDialogRootProps = React.ComponentProps<typeof AlertDialogPrimitive.Root>;

const AlertDialogTrigger = AlertDialogPrimitive.Trigger;

function AlertDialogPortal(props: React.ComponentProps<typeof AlertDialogPrimitive.Portal>) {
  return <AlertDialogPrimitive.Portal data-slot="alert-dialog-portal" {...props} />;
}

const AlertDialogOverlay = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Overlay
    ref={ref}
    data-slot="alert-dialog-overlay"
    className={cn(
      'fixed inset-0 z-[var(--z-overlay)] bg-[var(--color-overlay)]',
      'data-[state=open]:animate-in data-[state=open]:fade-in-0',
      'data-[state=closed]:animate-out data-[state=closed]:fade-out-0',
      className
    )}
    {...props}
  />
));
AlertDialogOverlay.displayName = 'AlertDialogOverlay';

const AlertDialogContent = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Content>
>(({ className, ...props }, ref) => (
  <AlertDialogPortal>
    <AlertDialogOverlay />
    <AlertDialogPrimitive.Content
      ref={ref}
      data-slot="alert-dialog-content"
      className={cn(
        'fixed left-1/2 top-1/2 z-[var(--z-dialog)] w-full max-w-sm -translate-x-1/2 -translate-y-1/2',
        'rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-surface-raised)]',
        'p-[var(--space-6)] shadow-[var(--shadow-lg)] duration-[var(--duration-slow)]',
        'data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95',
        'data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95',
        className
      )}
      {...props}
    />
  </AlertDialogPortal>
));
AlertDialogContent.displayName = 'AlertDialogContent';

function AlertDialogHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="alert-dialog-header"
      className={cn('flex flex-col gap-[var(--space-2)]', className)}
      {...props}
    />
  );
}

function AlertDialogFooter({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="alert-dialog-footer"
      className={cn(
        'mt-[var(--space-6)] flex items-center justify-end gap-[var(--space-3)]',
        className
      )}
      {...props}
    />
  );
}

const AlertDialogTitle = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Title>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Title
    ref={ref}
    data-slot="alert-dialog-title"
    className={cn(
      'text-[length:var(--text-base)] font-semibold text-[var(--color-text-primary)]',
      className
    )}
    {...props}
  />
));
AlertDialogTitle.displayName = 'AlertDialogTitle';

const AlertDialogDescription = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Description>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Description
    ref={ref}
    data-slot="alert-dialog-description"
    className={cn(
      'text-[length:var(--text-sm)] text-[var(--color-text-secondary)]',
      className
    )}
    {...props}
  />
));
AlertDialogDescription.displayName = 'AlertDialogDescription';

const AlertDialogAction = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Action>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Action>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Action
    ref={ref}
    data-slot="alert-dialog-action"
    className={cn(
      buttonVariants({ variant: 'primary' }),
      'cursor-pointer disabled:cursor-not-allowed',
      className
    )}
    {...props}
  />
));
AlertDialogAction.displayName = 'AlertDialogAction';

const AlertDialogCancel = React.forwardRef<
  React.ElementRef<typeof AlertDialogPrimitive.Cancel>,
  React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Cancel>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Cancel
    ref={ref}
    data-slot="alert-dialog-cancel"
    className={cn(
      buttonVariants({ variant: 'secondary' }),
      'cursor-pointer disabled:cursor-not-allowed',
      className
    )}
    {...props}
  />
));
AlertDialogCancel.displayName = 'AlertDialogCancel';

function ControlledAlertDialog({
  open,
  title,
  description,
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  destructive = false,
  confirmDisabled = false,
  onConfirm,
  onCancel,
  className,
}: AlertDialogProps) {
  const confirming = React.useRef(false);

  return (
    <AlertDialogPrimitive.Root
      open={open}
      onOpenChange={(next) => {
        if (!next) {
          if (!confirming.current) onCancel();
          confirming.current = false;
        }
      }}
    >
      <AlertDialogContent className={className}>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          {description && <AlertDialogDescription>{description}</AlertDialogDescription>}
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>{cancelLabel}</AlertDialogCancel>
          <AlertDialogAction
            className={destructive ? buttonVariants({ variant: 'destructive' }) : undefined}
            disabled={confirmDisabled}
            onClick={() => {
              confirming.current = true;
              onConfirm();
            }}
          >
            {confirmLabel}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialogPrimitive.Root>
  );
}

function isConvenienceProps(props: AlertDialogProps | AlertDialogRootProps): props is AlertDialogProps {
  return 'title' in props && 'onConfirm' in props && 'onCancel' in props;
}

function AlertDialog(props: AlertDialogProps): React.ReactElement;
function AlertDialog(props: AlertDialogRootProps): React.ReactElement;
function AlertDialog(props: AlertDialogProps | AlertDialogRootProps) {
  if (isConvenienceProps(props)) return <ControlledAlertDialog {...props} />;
  return <AlertDialogPrimitive.Root data-slot="alert-dialog" {...props} />;
}

export {
  AlertDialog,
  AlertDialogTrigger,
  AlertDialogPortal,
  AlertDialogOverlay,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogAction,
  AlertDialogCancel,
};

import * as React from 'react';
import { cva, type VariantProps } from 'class-variance-authority';
import { CheckmarkFilled, ErrorFilled, InformationFilled, WarningFilled } from '@/components/icons';
import { cn } from '@/lib/cn';

// Inline alert / banner. Color is always paired with an icon and text (N9).
// Error and warning alerts use role=alert so they are announced immediately.

const alertVariants = cva(
  'flex gap-3 rounded-[var(--radius-md)] border p-[var(--space-4)] text-[length:var(--text-sm)]',
  {
    variants: {
      variant: {
        error: 'bg-[var(--color-status-error-bg)] border-[var(--color-status-error-border)] text-[var(--color-status-error-text)]',
        warning: 'bg-[var(--color-status-warning-bg)] border-[var(--color-status-warning-border)] text-[var(--color-status-warning-text)]',
        success: 'bg-[var(--color-status-success-bg)] border-[var(--color-status-success-border)] text-[var(--color-status-success-text)]',
        info: 'bg-[var(--color-status-info-bg)] border-[var(--color-status-info-border)] text-[var(--color-status-info-text)]',
      },
    },
    defaultVariants: { variant: 'info' },
  }
);

const ICON = {
  error: ErrorFilled,
  warning: WarningFilled,
  success: CheckmarkFilled,
  info: InformationFilled,
} as const;

export interface AlertProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof alertVariants> {
  title?: string;
}

function Alert({ className, variant = 'info', title, children, role, ...props }: AlertProps) {
  const Icon = ICON[variant ?? 'info'];
  const defaultRole = variant === 'error' || variant === 'warning' ? 'alert' : 'status';
  const hasComposableChild = React.Children.toArray(children).some(
    (child) =>
      React.isValidElement(child) &&
      (child.type === AlertTitle || child.type === AlertDescription || child.type === AlertAction)
  );

  return (
    <div
      data-slot="alert"
      role={role ?? defaultRole}
      className={cn(alertVariants({ variant }), className)}
      {...props}
    >
      <Icon size={20} aria-hidden="true" className="mt-0.5 shrink-0" />
      <div className="flex min-w-0 flex-1 flex-col gap-1">
        {title && <AlertTitle>{title}</AlertTitle>}
        {hasComposableChild ? children : children && <AlertDescription>{children}</AlertDescription>}
      </div>
    </div>
  );
}

function AlertTitle({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="alert-title"
      className={cn('font-semibold', className)}
      {...props}
    />
  );
}

function AlertDescription({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="alert-description"
      className={cn('[&_a]:underline', className)}
      {...props}
    />
  );
}

function AlertAction({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="alert-action"
      className={cn('mt-[var(--space-2)] flex items-center gap-[var(--space-2)]', className)}
      {...props}
    />
  );
}

export { Alert, AlertTitle, AlertDescription, AlertAction, alertVariants };

'use client';

import { AspectRatio as AspectRatioPrimitive } from 'radix-ui';

function AspectRatio(props: React.ComponentProps<typeof AspectRatioPrimitive.Root>) {
  return <AspectRatioPrimitive.Root {...props} />;
}

export { AspectRatio };

import * as React from 'react';
import { cn } from '@/lib/cn';

export type AsyncStateStatus = 'loading' | 'error' | 'empty' | 'ready';

export interface AsyncStateProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  status: AsyncStateStatus;
  loading: React.ReactNode;
  error: React.ReactNode;
  empty: React.ReactNode;
  children: React.ReactNode;
}

function AsyncState({ status, loading, error, empty, children, className, ...props }: AsyncStateProps) {
  const content = {
    loading,
    error,
    empty,
    ready: children,
  }[status];

  return (
    <div
      className={cn('min-w-0', className)}
      aria-busy={status === 'loading' || undefined}
      {...props}
    >
      {content}
    </div>
  );
}

export { AsyncState };

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot } from "radix-ui"

import { cn } from "@/lib/cn"
import { Button } from "@/components/ui/button"

const attachmentVariants = cva(
  "group/attachment relative flex w-fit max-w-full min-w-0 shrink-0 flex-wrap rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-surface)] text-[var(--color-text-primary)] transition-colors duration-[var(--duration-fast)] focus-within:outline focus-within:outline-[var(--focus-ring-width)] focus-within:outline-[var(--color-focus-ring)] focus-within:outline-offset-[var(--focus-ring-offset)] has-[>a,>button]:hover:bg-[var(--color-surface-hover)] data-[state=error]:border-[var(--color-status-error-border)] data-[state=idle]:border-dashed",
  {
    variants: {
      size: {
        default:
          "gap-2 text-sm has-data-[slot=attachment-content]:px-2.5 has-data-[slot=attachment-content]:py-2 has-data-[slot=attachment-media]:p-2",
        sm: "gap-2.5 text-sm has-data-[slot=attachment-content]:px-2 has-data-[slot=attachment-content]:py-1.5 has-data-[slot=attachment-media]:p-1.5",
        xs: "gap-1.5 rounded-[var(--radius-md)] text-sm has-data-[slot=attachment-content]:px-1.5 has-data-[slot=attachment-content]:py-1 has-data-[slot=attachment-media]:p-1",
      },
      orientation: {
        horizontal: "min-w-40 items-center",
        vertical: "w-24 flex-col has-data-[slot=attachment-content]:w-30",
      },
    },
  }
)

function Attachment({
  className,
  state = "done",
  size = "default",
  orientation = "horizontal",
  ...props
}: React.ComponentProps<"div"> &
  VariantProps<typeof attachmentVariants> & {
    state?: "idle" | "uploading" | "processing" | "error" | "done"
  }) {
  return (
    <div
      data-slot="attachment"
      data-state={state}
      data-size={size}
      data-orientation={orientation}
      className={cn(attachmentVariants({ size, orientation }), className)}
      {...props}
    />
  )
}

const attachmentMediaVariants = cva(
  "relative flex aspect-square w-10 shrink-0 items-center justify-center overflow-hidden rounded-[var(--radius-md)] bg-[var(--color-surface-sunken)] text-[var(--color-text-primary)] group-data-[orientation=vertical]/attachment:w-full group-data-[size=sm]/attachment:w-8 group-data-[size=xs]/attachment:w-7 group-data-[size=xs]/attachment:rounded-[var(--radius-sm)] group-data-[state=error]/attachment:bg-[var(--color-status-error-bg)] group-data-[state=error]/attachment:text-[var(--color-status-error-text)] group-data-[orientation=vertical]/attachment:*:data-[slot=spinner]:size-6! [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 group-data-[orientation=vertical]/attachment:[&_svg:not([class*='size-'])]:size-6 group-data-[size=xs]/attachment:[&_svg:not([class*='size-'])]:size-3.5",
  {
    variants: {
      variant: {
        icon: "",
        image:
          "opacity-60 group-data-[state=done]/attachment:opacity-100 group-data-[state=idle]/attachment:opacity-100 *:[img]:aspect-square *:[img]:w-full *:[img]:object-cover",
      },
    },
    defaultVariants: {
      variant: "icon",
    },
  }
)

function AttachmentMedia({
  className,
  variant = "icon",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof attachmentMediaVariants>) {
  return (
    <div
      data-slot="attachment-media"
      data-variant={variant}
      className={cn(attachmentMediaVariants({ variant }), className)}
      {...props}
    />
  )
}

function AttachmentContent({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="attachment-content"
      className={cn(
        "max-w-full min-w-0 flex-1 leading-tight group-data-[orientation=vertical]/attachment:px-1",
        className
      )}
      {...props}
    />
  )
}

function AttachmentTitle({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="attachment-title"
      className={cn(
        "block max-w-full min-w-0 truncate font-medium group-data-[state=processing]/attachment:shimmer group-data-[state=uploading]/attachment:shimmer",
        className
      )}
      {...props}
    />
  )
}

function AttachmentDescription({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="attachment-description"
      className={cn(
        "mt-0.5 block min-w-0 truncate text-sm text-[var(--color-text-tertiary)] group-data-[state=error]/attachment:text-[var(--color-status-error-text)]",
        "max-w-full",
        className
      )}
      {...props}
    />
  )
}

function AttachmentActions({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="attachment-actions"
      className={cn(
        "relative z-[var(--z-sticky)] flex shrink-0 items-center group-data-[orientation=vertical]/attachment:absolute group-data-[orientation=vertical]/attachment:top-3 group-data-[orientation=vertical]/attachment:right-3 group-data-[orientation=vertical]/attachment:gap-1",
        className
      )}
      {...props}
    />
  )
}

function AttachmentAction({
  className,
  variant,
  size = "icon-xs",
  ...props
}: Omit<React.ComponentProps<typeof Button>, "size"> & {
  size?: React.ComponentProps<typeof Button>["size"] | "icon-xs"
}) {
  return (
    /* design-check-exempt: This compound wrapper must forward consumer className to Button to preserve its public API. */
    <Button
      data-slot="attachment-action"
      variant={variant ?? "ghost"}
      size={size === "icon-xs" ? "icon" : size}
      className={cn(className)}
      {...props}
    />
  )
}

function AttachmentTrigger({
  className,
  asChild = false,
  type,
  ...props
}: React.ComponentProps<"button"> & {
  asChild?: boolean
}) {
  const Comp = asChild ? Slot.Root : "button"

  return (
    <Comp
      data-slot="attachment-trigger"
      type={asChild ? undefined : (type ?? "button")}
      className={cn("absolute inset-0 z-[var(--z-dropdown)] cursor-pointer rounded-[var(--radius-lg)]", className)}
      {...props}
    />
  )
}

function AttachmentGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="attachment-group"
      className={cn(
        "flex min-w-0 scroll-fade-x snap-x snap-mandatory scroll-px-1 scrollbar-none gap-3 overflow-x-auto overscroll-x-contain py-1 *:data-[slot=attachment]:flex-none *:data-[slot=attachment]:snap-start",
        className
      )}
      {...props}
    />
  )
}

export {
  Attachment,
  AttachmentGroup,
  AttachmentMedia,
  AttachmentContent,
  AttachmentTitle,
  AttachmentDescription,
  AttachmentActions,
  AttachmentAction,
  AttachmentTrigger,
}

import * as React from 'react';
import { cn } from '@/lib/cn';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';

interface AvatarGroupItem {
  src?: string;
  alt: string;
  fallback: string;
}

interface AvatarGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  items: AvatarGroupItem[];
  max?: number;
}

function AvatarGroup({ items, max = 4, className, ...props }: AvatarGroupProps) {
  const visible = items.slice(0, Math.max(0, max));
  const remaining = Math.max(0, items.length - visible.length);

  return (
    <div className={cn('flex items-center', className)} aria-label={`${items.length} people`} {...props}>
      {visible.map((item, index) => (
        <Avatar
          key={`${item.alt}-${index}`}
          className={cn('border-2 border-[var(--color-surface)]', index > 0 && '-ml-[var(--space-2)]')}
        >
          {item.src && <AvatarImage src={item.src} alt={item.alt} />}
          <AvatarFallback aria-label={item.alt}>{item.fallback}</AvatarFallback>
        </Avatar>
      ))}
      {remaining > 0 && (
        <span className="-ml-[var(--space-2)] inline-flex size-10 items-center justify-center rounded-[var(--radius-full)] border-2 border-[var(--color-surface)] bg-[var(--color-surface-sunken)] px-[var(--space-2)] text-[length:var(--text-sm)] font-medium text-[var(--color-text-secondary)]">
          +{remaining}
        </span>
      )}
    </div>
  );
}

export { AvatarGroup };
export type { AvatarGroupItem, AvatarGroupProps };

'use client';

import * as React from 'react';
import { Avatar as AvatarPrimitive } from 'radix-ui';

import { cn } from '@/lib/cn';

function Avatar({
  className,
  size = 'default',
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Root> & {
  size?: 'default' | 'sm' | 'lg';
}) {
  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      data-size={size}
      className={cn(
        'group/avatar relative flex size-8 shrink-0 select-none rounded-[var(--radius-full)]',
        'border border-[var(--color-border-subtle)]',
        'data-[size=lg]:size-10 data-[size=sm]:size-6',
        className
      )}
      {...props}
    />
  )
}

function AvatarImage({
  className,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Image>) {
  return (
    <AvatarPrimitive.Image
      data-slot="avatar-image"
      className={cn(
        'aspect-square size-full rounded-[var(--radius-full)] object-cover',
        className
      )}
      {...props}
    />
  )
}

function AvatarFallback({
  className,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Fallback>) {
  return (
    <AvatarPrimitive.Fallback
      data-slot="avatar-fallback"
      className={cn(
        'flex size-full items-center justify-center rounded-[var(--radius-full)]',
        'bg-[var(--color-surface-sunken)] text-[length:var(--text-sm)] text-[var(--color-text-secondary)]',
        className
      )}
      {...props}
    />
  )
}

type AvatarBadgeProps = Omit<
  React.ComponentProps<'span'>,
  'aria-label' | 'role'
> & {
  label: string;
};

function AvatarBadge({
  className,
  children,
  label,
  ...props
}: AvatarBadgeProps) {
  return (
    <span
      data-slot="avatar-badge"
      role="status"
      className={cn(
        'absolute bottom-0 right-0 inline-flex items-center justify-center select-none',
        'rounded-[var(--radius-full)] bg-[var(--color-status-success)] text-[var(--color-text-on-status)]',
        'ring-2 ring-[var(--color-surface)]',
