      role="list"
      className={cn('divide-y divide-[var(--color-border-subtle)]', className)}
      {...props}
    />
  );
}

interface DataRowCommonProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'onSelect'> {
  leading?: React.ReactNode;
  trailing?: React.ReactNode;
}

interface StaticDataRowProps extends DataRowCommonProps {
  href?: undefined;
  onSelect?: undefined;
  selectLabel?: undefined;
}

interface LinkDataRowProps extends DataRowCommonProps {
  /** Makes the row a link; the row content becomes the click target via a stretched overlay. */
  href: string;
  onSelect?: undefined;
  /** Accessible name for the overlay control, since the visible text sits outside it. */
  selectLabel: string;
}

interface ButtonDataRowProps extends DataRowCommonProps {
  href?: undefined;
  /** Makes the row a button; the row content becomes the click target via a stretched overlay. */
  onSelect: () => void;
  /** Accessible name for the overlay control, since the visible text sits outside it. */
  selectLabel: string;
}

export type DataRowProps = StaticDataRowProps | LinkDataRowProps | ButtonDataRowProps;

const overlay = [
  'absolute inset-0 cursor-pointer rounded-[inherit]',
  'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset',
  'focus-visible:ring-[var(--color-focus-ring)]',
].join(' ');

function DataRow({
  href,
  onSelect,
  selectLabel,
  leading,
  trailing,
  children,
  className,
  ...props
}: DataRowProps) {
  const interactive = Boolean(href || onSelect);

  return (
    <div
      role="listitem"
      className={cn(
        'relative flex items-center gap-[var(--space-3)]',
        'px-[var(--space-2)] py-[var(--space-3)]',
        interactive && [
          'rounded-[var(--radius-sm)] transition-colors duration-[var(--duration-fast)]',
          'hover:bg-[var(--color-surface-hover)]',
        ],
        className
      )}
      {...props}
    >
      {href ? (
        <Link href={href} className={overlay}>
          <span className="sr-only">{selectLabel}</span>
        </Link>
      ) : onSelect ? (
        <button type="button" onClick={onSelect} aria-label={selectLabel} className={overlay} />
      ) : null}
      {leading && <span className="shrink-0">{leading}</span>}
      <div className="min-w-0 flex-1 text-[length:var(--text-sm)] text-[var(--color-text-primary)]">
        {children}
      </div>
      {trailing && <span className="relative shrink-0">{trailing}</span>}
    </div>
  );
}

export { DataList, DataRow };

'use client';

import * as React from 'react';
import {
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
  type ColumnDef,
  type SortingState,
} from '@tanstack/react-table';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';

interface DataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[];
  data: TData[];
  searchPlaceholder?: string;
  emptyMessage?: string;
  pageSize?: number;
}

function DataTable<TData, TValue>({
  columns,
  data,
  searchPlaceholder = 'Search',
  emptyMessage = 'No results found',
  pageSize = 10,
}: DataTableProps<TData, TValue>) {
  const [sorting, setSorting] = React.useState<SortingState>([]);
  const [globalFilter, setGlobalFilter] = React.useState('');
  const table = useReactTable({
    data,
    columns,
    state: { sorting, globalFilter },
    onSortingChange: setSorting,
    onGlobalFilterChange: setGlobalFilter,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    initialState: { pagination: { pageSize } },
  });

  return (
    <div className="flex flex-col gap-[var(--space-4)]">
      <label className="flex flex-col gap-[var(--space-2)] text-[length:var(--text-sm)] font-medium text-[var(--color-text-primary)]">
        Search table
        <Input
          type="search"
          value={globalFilter}
          onChange={(event) => setGlobalFilter(event.target.value)}
          placeholder={searchPlaceholder}
        />
      </label>
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <TableHead key={header.id}>
                  {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table.getRowModel().rows.length ? (
            table.getRowModel().rows.map((row) => (
              <TableRow key={row.id} data-state={row.getIsSelected() ? 'selected' : undefined}>
                {row.getVisibleCells().map((cell) => (
                  <TableCell key={cell.id}>{flexRender(cell.column.columnDef.cell, cell.getContext())}</TableCell>
                ))}
              </TableRow>
            ))
          ) : (
            <TableRow>
              <TableCell colSpan={columns.length} className="h-24 text-center text-[var(--color-text-secondary)]">
                {emptyMessage}
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
      <div className="flex items-center justify-between gap-[var(--space-4)]">
        <p className="text-[length:var(--text-sm)] text-[var(--color-text-secondary)]">
          Page {table.getState().pagination.pageIndex + 1} of {Math.max(1, table.getPageCount())}
        </p>
        <div className="flex items-center gap-[var(--space-2)]">
          <Button variant="secondary" onClick={() => table.previousPage()} disabled={!table.getCanPreviousPage()}>
            Previous
          </Button>
          <Button variant="secondary" onClick={() => table.nextPage()} disabled={!table.getCanNextPage()}>
            Next
          </Button>
        </div>
      </div>
    </div>
  );
}

export { DataTable };
export type { DataTableProps };

