        "last:mt-0 nth-last-2:-mt-1",
        "[&>a]:text-[var(--color-text-link)] [&>a]:underline [&>a]:underline-offset-4 [&>a:hover]:text-[var(--color-text-primary)]",
        className
      )}
      {...props}
    />
