  FieldLabel,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLegend,
  FieldSeparator,
  FieldSet,
  FieldContent,
  FieldTitle,
}

'use client';

import * as React from 'react';
import { Upload } from '@/components/icons';
import { cn } from '@/lib/cn';

interface FileUploadProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'type' | 'onChange'> {
  label: string;
  description?: string;
  error?: string;
  onFilesChange?: (files: File[]) => void;
}

const FileUpload = React.forwardRef<HTMLInputElement, FileUploadProps>(
  ({ label, description, error, onFilesChange, className, disabled, id, ...props }, forwardedRef) => {
    const generatedId = React.useId();
    const inputId = id ?? generatedId;
    const descriptionId = description ? `${inputId}-description` : undefined;
    const errorId = error ? `${inputId}-error` : undefined;
    const describedBy = [descriptionId, errorId].filter(Boolean).join(' ') || undefined;
    const [dragging, setDragging] = React.useState(false);

    const emitFiles = (list: FileList | null) => onFilesChange?.(Array.from(list ?? []));

    return (
      <div className={cn('flex flex-col gap-[var(--space-2)]', className)}>
        <label htmlFor={inputId} className="text-[length:var(--text-sm)] font-medium text-[var(--color-text-primary)]">
          {label}
        </label>
        {description && (
          <p id={descriptionId} className="text-[length:var(--text-sm)] text-[var(--color-text-tertiary)]">
            {description}
          </p>
        )}
        <label
          htmlFor={inputId}
          onDragEnter={(event) => {
            event.preventDefault();
            if (!disabled) setDragging(true);
          }}
          onDragOver={(event) => event.preventDefault()}
          onDragLeave={() => setDragging(false)}
          onDrop={(event) => {
            event.preventDefault();
            setDragging(false);
            if (!disabled) emitFiles(event.dataTransfer.files);
          }}
          className={cn(
            'relative flex min-h-32 cursor-pointer flex-col items-center justify-center gap-[var(--space-2)]',
            'rounded-[var(--radius-md)] border border-dashed border-[var(--color-border-strong)] p-[var(--space-6)]',
            'bg-[var(--color-surface)] text-center transition-colors duration-[var(--duration-fast)]',
            'hover:bg-[var(--color-surface-hover)] active:bg-[var(--color-surface-active)]',
            'focus-within:ring-2 focus-within:ring-[var(--color-focus-ring)] focus-within:ring-offset-2',
            dragging && 'bg-[var(--color-brand-subtle)]',
            disabled && 'cursor-not-allowed opacity-50',
            error && 'border-[var(--color-status-error)]',
          )}
        >
          <Upload size={24} aria-hidden="true" />
          <span className="text-[length:var(--text-sm)] font-medium text-[var(--color-text-primary)]">
            Choose files or drop them here
          </span>
          <input
            ref={forwardedRef}
            id={inputId}
            type="file"
            disabled={disabled}
            aria-invalid={error ? true : undefined}
            aria-describedby={describedBy}
            className="absolute inset-0 cursor-pointer opacity-0 disabled:cursor-not-allowed"
            onChange={(event) => emitFiles(event.currentTarget.files)}
            {...props}
          />
        </label>
        {error && (
          <p id={errorId} role="alert" className="text-[length:var(--text-sm)] text-[var(--color-status-error-text)]">
            {error}
          </p>
        )}
      </div>
    );
  },
);
FileUpload.displayName = 'FileUpload';

export { FileUpload };
export type { FileUploadProps };

'use client';

// FormField wires label, hint, and error to the control with correct
// htmlFor/id and aria-describedby (rules A4, N8, N9, A11).
// Always use FormField for form inputs; never a bare <Input> with placeholder-as-label.

import * as React from 'react';
import { ErrorFilled } from '@/components/icons';
import { cn } from '@/lib/cn';

/* ---------- Label ---------- */
const Label = React.forwardRef<HTMLLabelElement, React.LabelHTMLAttributes<HTMLLabelElement>>(
  ({ className, ...props }, ref) => (
    <label
      ref={ref}
      className={cn(
        'text-[length:var(--text-sm)] font-medium text-[var(--color-text-primary)]',
        'peer-disabled:opacity-50',
        className
      )}
      {...props}
    />
  )
);
Label.displayName = 'Label';

/* ---------- Input ---------- */
export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  invalid?: boolean;
}

const Input = React.forwardRef<HTMLInputElement, InputProps>(
  ({ className, invalid, type, ...props }, ref) => (
    <input
      type={type}
      ref={ref}
      {...props}
      aria-invalid={invalid || props['aria-invalid'] || undefined}
      className={cn(
        'flex h-11 w-full rounded-[var(--radius-sm)] px-3',
        'bg-[var(--color-surface)] text-[length:var(--text-sm)] text-[var(--color-text-primary)]',
        'border border-[var(--color-border)]',
        'placeholder:text-[var(--color-text-tertiary)]',
        'transition-colors duration-[var(--duration-fast)]',
        'hover:border-[var(--color-border-strong)]',
        'disabled:cursor-not-allowed disabled:opacity-50',
        invalid && 'border-[var(--color-status-error)]',
        className
      )}
    />
  )
);
Input.displayName = 'Input';

/* ---------- Textarea ---------- */
const Textarea = React.forwardRef<
  HTMLTextAreaElement,
  React.TextareaHTMLAttributes<HTMLTextAreaElement> & { invalid?: boolean }
>(({ className, invalid, ...props }, ref) => (
  <textarea
    ref={ref}
    {...props}
    aria-invalid={invalid || props['aria-invalid'] || undefined}
    className={cn(
      'flex min-h-24 w-full rounded-[var(--radius-sm)] px-3 py-2',
      'bg-[var(--color-surface)] text-[length:var(--text-sm)] text-[var(--color-text-primary)]',
      'border border-[var(--color-border)]',
      'placeholder:text-[var(--color-text-tertiary)]',
      'transition-colors duration-[var(--duration-fast)]',
      'hover:border-[var(--color-border-strong)]',
      'disabled:cursor-not-allowed disabled:opacity-50',
      invalid && 'border-[var(--color-status-error)]',
      className
    )}
  />
));
Textarea.displayName = 'Textarea';

/* ---------- FormField ---------- */
export interface FormFieldProps {
  label: string;
  hint?: string;
  error?: string;
  required?: boolean;
  children: React.ReactElement;
  className?: string;
}

function FormField({ label, hint, error, required, children, className }: FormFieldProps) {
  const id = React.useId();
  const hintId = hint ? `${id}-hint` : undefined;
  const errorId = error ? `${id}-error` : undefined;
  const childProps = (children as React.ReactElement<Record<string, unknown>>).props;
  const existingDescribedBy = childProps['aria-describedby'] as string | undefined;
  const describedBy = [existingDescribedBy, hintId, errorId].filter(Boolean).join(' ') || undefined;

  return (
    <div className={cn('flex flex-col gap-[var(--space-2)]', className)}>
      <Label htmlFor={id}>
        {label}
        {required && (
          <span aria-hidden="true" className="ml-1 text-[var(--color-status-error-text)]">*</span>
        )}
      </Label>
      {hint && (
        <p id={hintId} className="text-[length:var(--text-sm)] text-[var(--color-text-tertiary)]">
          {hint}
        </p>
      )}
      {React.cloneElement(children as React.ReactElement<Record<string, unknown>>, {
        id,
        'aria-describedby': describedBy,
        invalid: Boolean(error) || undefined,
        required: required || undefined,
      })}
      {error && (
        <p
          id={errorId}
          role="alert"
          className="flex items-center gap-1.5 text-[length:var(--text-sm)] text-[var(--color-status-error-text)]"
        >
          <ErrorFilled size={16} aria-hidden="true" />
          {error}
        </p>
      )}
    </div>
  );
}

export { Label, Input, Textarea, FormField };

